/* @autogenerated */
package net.civeira.phylax.features.oauth.client.application;

import java.time.Duration;
import java.time.Instant;
import java.util.Collection;
import java.util.List;
import java.util.Map;
import java.util.Optional;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.features.oauth.client.domain.ClientDetails;
import net.civeira.phylax.features.oauth.client.domain.gateway.ClientJwtSignatureGateway;
import net.civeira.phylax.features.oauth.client.domain.gateway.JwtReplayGateway;

/**
 * Verifies a {@code private_key_jwt} client assertion (RFC 7523 §3, OIDC Core §9, task 3.2).
 *
 * <ul>
 * <li>Signed with a key of the client's JWKS and, when it registered one, its
 * {@code token_endpoint_auth_signing_alg}; only asymmetric algorithms.</li>
 * <li>{@code iss} and {@code sub} are the client.</li>
 * <li>{@code aud} names this server: its issuer or one of its endpoints.</li>
 * <li>{@code exp} is required and in the future, and the assertion lives at most an hour.</li>
 * <li>{@code jti} is required and used only once, under the purpose shared with request objects:
 * the same JWT cannot authenticate a client and also carry an authorization request.</li>
 * <li>An assertion with authorization parameters ({@code response_type}) is a request object, not
 * an assertion.</li>
 * </ul>
 */
@Slf4j
@ApplicationScoped
@RequiredArgsConstructor
public class ClientAssertionVerifier {

  private static final Duration MAX_LIFETIME = Duration.ofHours(1);

  private final ClientJwtSignatureGateway signatures;
  private final JwtReplayGateway replays;

  /**
   * Verifies the assertion of a client.
   *
   * @param tenant tenant of the endpoint
   * @param issuer issuer of the tenant; its endpoints are below it
   * @param client client named by the assertion, registered for private_key_jwt
   * @param jwt compact assertion
   * @return true when the client is authenticated
   */
  public boolean verify(String tenant, String issuer, ClientDetails client, String jwt) {
    Optional<Map<String, Object>> verified =
        signatures.verify(client, jwt, client.getTokenEndpointAuthSigningAlg());
    if (verified.isEmpty()) {
      return rejected(client, "signature");
    }
    Map<String, Object> claims = verified.get();
    String clientId = client.getClientId();
    if (!clientId.equals(claims.get("iss")) || !clientId.equals(claims.get("sub"))) {
      return rejected(client, "iss and sub must be the client");
    }
    if (claims.containsKey("response_type")) {
      return rejected(client, "a request object is not an assertion");
    }
    if (audiences(claims.get("aud")).stream().noneMatch(aud -> forThisServer(aud, issuer))) {
      return rejected(client, "audience");
    }
    Instant now = Instant.now();
    Instant exp = instant(claims.get("exp"));
    if (exp == null || !exp.isAfter(now)) {
      return rejected(client, "expired or without exp");
    }
    Instant iat = instant(claims.get("iat"));
    Instant start = instant(claims.get("nbf"));
    start = start != null ? start : iat != null ? iat : now;
    if (Duration.between(start, exp).compareTo(MAX_LIFETIME) > 0) {
      return rejected(client, "lifetime longer than an hour");
    }
    if (!(claims.get("jti") instanceof String jti) || jti.isBlank()) {
      return rejected(client, "without jti");
    }
    if (!replays.firstUse(tenant, clientId, JwtReplayGateway.CLIENT_SIGNED, jti, exp)) {
      return rejected(client, "jti already used");
    }
    return true;
  }

  /**
   * The issuer itself or one of its endpoints ({@code <issuer>/token}, {@code /par-request},
   * {@code /introspect}...), so the same assertion rules serve every authenticated endpoint.
   */
  private static boolean forThisServer(String aud, String issuer) {
    return aud.equals(issuer) || aud.startsWith(issuer + "/") && aud.indexOf('?') < 0
        && aud.substring(issuer.length() + 1).matches("[a-z-]+");
  }

  private static boolean rejected(ClientDetails client, String reason) {
    log.info("Client assertion of {} rejected: {}", client.getClientId(), reason);
    return false;
  }

  private static List<String> audiences(Object aud) {
    if (aud instanceof String single) {
      return List.of(single);
    }
    if (aud instanceof Collection<?> values) {
      return values.stream().map(String::valueOf).toList();
    }
    return List.of();
  }

  private static Instant instant(Object value) {
    if (value instanceof Number seconds) {
      return Instant.ofEpochSecond(seconds.longValue());
    }
    if (value instanceof java.util.Date date) {
      return date.toInstant();
    }
    return null;
  }
}
